'use strict';
const $=id=>document.getElementById(id);const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const average=a=>a.length?a.reduce((s,n)=>s+n,0)/a.length:NaN;const fix=(x,n=2)=>Number.isFinite(x)?x.toFixed(n):'—';const score=r=>r.quality_score==null?NaN:Number(r.quality_score);
const PRIOR_N=20;let evidenceMode='conservative',minimumN=10;
function cohortStats(g){const sample=filtered.map(score).filter(n=>Number.isFinite(n)&&n>=0&&n<=5);const mu=sample.length?average(sample):3;const variance=sample.length>1?Math.max(.25,average(sample.map(x=>(x-mu)**2))):1.5;const sum=g.rows.reduce((a,r)=>a+score(r),0);const estimate=(sum+PRIOR_N*mu)/(g.n+PRIOR_N);const sd=Math.sqrt(variance/(g.n+PRIOR_N));const lb=Math.max(0,estimate-1.96*sd),ub=Math.min(5,estimate+1.96*sd);return {...g,adjusted:estimate,low:lb,high:ub,uncertainty:ub-lb,reliability:g.n/(g.n+PRIOR_N),eligible:g.n>=minimumN}}
function evidence(g){return cohortStats(g)}
function orderGroups(data,mode='score'){return data.map(evidence).sort((a,b)=>{if(evidenceMode==='raw')return mode==='count'?b.n-a.n||b.avg-a.avg:mode==='numeric'?Number(a.name)-Number(b.name):b.avg-a.avg||b.n-a.n;if(mode==='numeric')return Number(a.name)-Number(b.name);if(mode==='count')return b.n-a.n||b.low-a.low;return (b.eligible?1:0)-(a.eligible?1:0)||b.low-a.low||b.n-a.n})}
function evidenceLegend(){return `<div class="evidence-legend"><span>● Thick fill: confidence-adjusted mean</span><span>│ Band: approximate 95% interval</span><span>n below ${minimumN}: exploratory</span><span>Ranked by lower confidence bound</span></div>`}
function meanTooltip(x){return `${x.name}: raw ${fix(x.avg)} / 5 | adjusted ${fix(x.adjusted)} | approx. 95% interval ${fix(x.low)}–${fix(x.high)} | n=${x.n}`}

let rows=[],filtered=[],view='explorer',page=0;let captionFilter='all';const LIMIT=45;
const labels={tags:['REVIEW OBSERVATIONS','What listeners <i>noticed.</i>','Structured positive and negative observations linked to current review revisions.'],explorer:['GBR RESEARCH / EXPLORER','The <i>Experiment Floor.</i>','Two-variable heatmap and empirical simulator in one workspace.'],overview:['ARCHIVE AUDIT','Mission <i>control.</i>','Data readiness and outstanding evidence gaps.'],parameters:['GENERATION CONTROL','Twist the <i>dials.</i>','Does more guidance, more sampling or a different algorithm actually sound better?'],genres:['SONGS / GENRES / STYLES','A galaxy of <i>sound.</i>','Explore which compositions and musical treatments rise above the noise.'],audio:['FLAC RESEARCH','Acoustic <i>fingerprints.</i>','Compare measured distributions, and see what they cannot tell us.'],precision:['COMPUTE RESEARCH','Quality has <i>a cost.</i>','Encoder and DiT precision across pods, with verified cost and quality joins.'],simulator:['PREDICTIVE WORKBENCH','Test the <i>possibilities.</i>','Explore acceptance, failure and uncertainty across generation settings.'],archive:['INDIVIDUAL GENERATIONS','The recording <i>vault.</i>','Every generation, every rating, every parameter. Select a row to inspect its record.']};
function groups(key,rs=filtered){const map=new Map;rs.filter(rated).forEach(r=>{let k=typeof key==='function'?key(r):r[key];k=k==null||k===''?'Unknown':String(k);if(!map.has(k))map.set(k,[]);map.get(k).push(r)});return [...map].map(([name,a])=>({name,n:a.length,avg:average(a.map(score)),good:a.filter(r=>score(r)>=4).length,poor:a.filter(r=>score(r)<=2).length,rows:a}))}
function sampleNote(n){return n<5?'Tiny sample — exploratory only':n<15?'Small sample — interpret cautiously':'Observed association, not a causal effect'}
function panel(title,tag,inside,note='',wide=false){return `<article class="instrument ${wide?'wide':''}"><div class="cap"><h3>${title}</h3><small>${tag}</small></div>${inside}${note?`<p class="subtext">${note}</p>`:''}</article>`}
function section(title,desc){return `<div class="section-prelude"><h2>${title}</h2><p>${desc}</p></div>`}
function barPlot(data,{limit=13,sort='count',showCount=true}={}){let d=(sort==='input'?data.map(evidence):orderGroups(data,sort)).filter(x=>Number.isFinite(x.avg)).slice(0,limit);if(!d.length)return '<div class="empty">No matching measurements.</div>';return `<div class="evidence-rows">${d.map(x=>{const position=evidenceMode==='raw'?x.avg:x.adjusted;return `<div class="horizontal-bar evidence-row ${x.eligible?'':'tentative'}" title="${safe(meanTooltip(x))}"><span class="name">${safe(x.name)}${!x.eligible?'<small class="low-n">LOW N</small>':''}</span><span class="track"><span class="interval" style="left:${(x.low/5*100).toFixed(1)}%;width:${((x.high-x.low)/5*100).toFixed(1)}%"></span><b style="width:${(position/5*100).toFixed(1)}%"></b><i class="conf-marker" style="left:${(x.low/5*100).toFixed(1)}%"></i></span><span class="number">${fix(position)} <small>n=${x.n}</small>${evidenceMode!=='raw'?`<small class="raw-mean">raw ${fix(x.avg)}</small>`:''}</span></div>`}).join('')}</div>${evidenceLegend()}` }
let plotScale='zoom';
function plotControls(){return `<div class="plot-scale-controls"><div><strong>EXPERIMENT CHART SCALE</strong><small>Zoom emphasises differences; intervals and group sizes remain visible.</small></div><div class="plot-scale-buttons" role="group" aria-label="Experiment graph scale">${[['zoom','ZOOMED'],['full','FULL 0–5'],['delta','Δ FROM MEAN']].map(([id,label])=>`<button type="button" data-plot-scale="${id}" class="${plotScale===id?'active':''}" aria-pressed="${plotScale===id}">${label}</button>`).join('')}</div></div>`}
function linePlot(data){
  const d=orderGroups(data.filter(x=>Number.isFinite(x.avg)),'numeric');
  if(!d.length)return '<div class="empty">No measurements.</div>';
  const W=690,H=282,L=54,R=25,T=30,B=56;
  const baseline=average(filtered.map(score).filter(Number.isFinite));
  const delta=plotScale==='delta',full=plotScale==='full';
  const center=Number.isFinite(baseline)?baseline:2.5;
  const transformed=d.map(x=>{
    const m=evidenceMode==='raw'?x.avg:x.adjusted;
    const offset=delta?center:0;
    return {...x,value:m-offset,lo:x.low-offset,hi:x.high-offset};
  });
  const limits=transformed.flatMap(x=>[x.value,x.lo,x.hi]);
  let min,max;
  if(full){min=0;max=5}
  else{
    let lo=Math.min(...limits),hi=Math.max(...limits);
    if(delta){lo=Math.min(lo,0);hi=Math.max(hi,0)}
    else {lo=Math.min(lo,center);hi=Math.max(hi,center)}
    const spread=Math.max(.12,hi-lo),padding=Math.max(.045,spread*.13);
    min=Math.floor((lo-padding)*20)/20;
    max=Math.ceil((hi+padding)*20)/20;
    if(!delta){min=Math.max(0,min);max=Math.min(5,max)}
    if(max-min<.2){const mid=(max+min)/2;min=mid-.1;max=mid+.1}
  }
  const xx=i=>L+i*(W-L-R)/Math.max(d.length-1,1);
  const yy=v=>T+(max-v)/(max-min)*(H-T-B);
  const ticks=Array.from({length:5},(_,i)=>min+(max-min)*i/4);
  const axis=full?'Full rating scale 0–5':delta?'Difference from filtered mean':'Zoomed rating scale';
  const line=transformed.map((x,i)=>`${xx(i)},${yy(x.value)}`).join(' ');
  const clamp=v=>Math.max(T,Math.min(H-B,yy(v)));
  const base=delta?0:center;
  const guide=base>=min&&base<=max?`<line class="plot-baseline" x1="${L}" x2="${W-R}" y1="${yy(base)}" y2="${yy(base)}"/><text x="${W-R-2}" y="${yy(base)-6}" text-anchor="end" class="reference-label">${delta?'ZERO / AVERAGE':'FILTERED MEAN'}</text>`:'';
  const grid=ticks.map(n=>`<line class="grid" x1="${L}" x2="${W-R}" y1="${yy(n)}" y2="${yy(n)}"/><text x="7" y="${yy(n)+4}">${delta?(n>0?'+':'')+fix(n,2):fix(n,2)}</text>`).join('');
  return `<div class="plot"><div class="plot-range-note">${axis}: <b>${fix(min,2)} to ${fix(max,2)}</b> · filtered mean ${fix(center,2)}/5</div><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${axis}. Confidence-adjusted scores, approximate intervals and sample counts.">${grid}${guide}<line class="axis" x1="${L}" x2="${W-R}" y1="${H-B}" y2="${H-B}"/>${transformed.map((x,i)=>`<line class="confidence-whisker ${x.eligible?'':'low-evidence'}" x1="${xx(i)}" x2="${xx(i)}" y1="${clamp(x.hi)}" y2="${clamp(x.lo)}"/><line class="confidence-whisker ${x.eligible?'':'low-evidence'}" x1="${xx(i)-6}" x2="${xx(i)+6}" y1="${clamp(x.lo)}" y2="${clamp(x.lo)}"/><line class="confidence-whisker ${x.eligible?'':'low-evidence'}" x1="${xx(i)-6}" x2="${xx(i)+6}" y1="${clamp(x.hi)}" y2="${clamp(x.hi)}"/>`).join('')}<polyline fill="none" stroke="#d6ad62" stroke-width="2.5" points="${line}"/>${transformed.map((x,i)=>`<circle class="dot ${x.eligible?'':'low-evidence'}" cx="${xx(i)}" cy="${yy(x.value)}" r="${Math.max(4,Math.min(10,3+Math.sqrt(x.n)/2))}" fill="${x.eligible?'#e9b865':'#9a8980'}"><title>${safe(meanTooltip(x))}${delta?' | delta '+fix(x.value,3):''}</title></circle><text x="${xx(i)}" y="${H-22}" text-anchor="middle">${safe(x.name)}</text><text class="sample-count" x="${xx(i)}" y="${H-6}" text-anchor="middle">n=${x.n}</text>`).join('')}</svg></div>${evidenceLegend()}`;
}
function scatter(key,label){const d=filtered.filter(r=>rated(r)&&r[key]!=null&&Number.isFinite(+r[key]));if(!d.length)return '<div class="empty">No audio measurements in this selection.</div>';const W=690,H=290,L=55,R=23,T=22,B=48,vals=d.map(r=>+r[key]),min=Math.min(...vals),max=Math.max(...vals),delta=max-min||1;let dots=d.map((r,i)=>{const x=L+((+r[key]-min)/delta)*(W-L-R),y=T+((5-score(r))/5)*(H-T-B),color=['#965e69','#a86e67','#ac875d','#c7b777','#a5c090','#e1b968'][Math.floor(score(r))];return `<circle class="dot" cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="3.7" opacity=".69" fill="${color}"><title>${safe(r.title||r.audio_file)} · ${fix(+r[key])} · grade ${score(r)}</title></circle>`}).join('');return `<div class="plot"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${safe(label)} versus listening grade">${[0,1,2,3,4,5].map(n=>{const y=T+(5-n)/5*(H-T-B);return `<line class="grid" x1="${L}" x2="${W-R}" y1="${y}" y2="${y}"/><text x="10" y="${y+4}">${n} / 5</text>`}).join('')}<line class="axis" x1="${L}" x2="${W-R}" y1="${H-B}" y2="${H-B}"/><text x="${L}" y="${H-16}">${fix(min,1)}</text><text x="${W-R}" y="${H-16}" text-anchor="end">${fix(max,1)}</text>${dots}</svg></div><p class="subtext">${d.length} real FLAC profiles. X axis: ${safe(label)}. Y axis: human rating. Hover any point for the recording name.</p>`}
function overview(){
 const total=filtered.length, prof=filtered.filter(r=>r.duration!=null).length, labelled=filtered.filter(r=>r.caption_source==='sample'||r.caption_source==='custom').length, missingYaml=filtered.filter(r=>r.missing_yaml).length;
 const fields=[['CAPTION PROVENANCE',labelled,total,'Records identifying sample or custom source'],['AUDIO PROFILE',prof,total,'Recordings with computed acoustics'],['YAML METADATA',total-missingYaml,total,'Generations with their source YAML'],['GENRE CLUSTER',filtered.filter(r=>r.cluster).length,total,'Generations with a defined genre group']];
 const coverage=fields.map(([title,n,d,why])=>`<div class="mission-readiness"><div><strong>${title}</strong><small>${why}</small></div><div class="mission-rail"><i style="width:${d?100*n/d:0}%"></i></div><b>${n.toLocaleString()} / ${d.toLocaleString()}</b></div>`).join('');
 const uncertain=groups(r=>[r.sampler,r.scheduler].filter(Boolean).join(' / ')).filter(g=>g.name&&g.n<minimumN).sort((a,b)=>a.n-b.n).slice(0,8);
 return section('Mission control / Archive health','This page audits the dataset: completeness, missing metadata and where the evidence is thin. It is not another copy of the analysis charts.')+panel('Data readiness','DATA QUALITY / OBSERVED COVERAGE',`<div class="mission-readiness-list">${coverage}</div>`,'A missing field is excluded from comparisons involving that field.',true)+panel('Uncertain sampler / scheduler cohorts','WHERE WE NEED MORE OBSERVATIONS',`<div class="mission-gaps">${uncertain.length?uncertain.map(g=>`<div><span>${safe(g.name)}</span><strong>n=${g.n}</strong><small>${Math.max(0,minimumN-g.n)} to threshold</small></div>`).join(''):'All observed pairs meet the current threshold.'}</div>`,'Low coverage does not mean low quality. Use the Experiment Floor to explore candidate settings.',true);
}
function heat(){const rs=filtered.filter(r=>rated(r)&&r.sampler&&r.scheduler);const sam=[...new Set(rs.map(r=>r.sampler))].sort(),sch=[...new Set(rs.map(r=>r.scheduler))].sort();if(!sam.length)return '<div class="empty">No algorithms recorded.</div>';const cell=(a,b)=>{const x=rs.filter(r=>r.sampler===a&&r.scheduler===b);if(!x.length)return '<td>—</td>';const g=evidence({name:`${a} / ${b}`,n:x.length,avg:average(x.map(score)),rows:x});const shown=evidenceMode==='raw'?g.avg:g.adjusted;const alpha=g.eligible?(.09+(shown-1)/4*.55).toFixed(2):.06;return `<td class="${g.eligible?'':'tentative'}" style="background:rgba(229,177,88,${alpha})" title="${safe(meanTooltip(g))}">${fix(shown)}<br><small>n=${g.n}${!g.eligible?' · LOW N':''}</small></td>`};return `<div class="plot"><table class="heat-table"><thead><tr><th>SAMPLER ↓ / SCHEDULER →</th>${sch.map(s=>`<th>${safe(s)}</th>`).join('')}</tr></thead><tbody>${sam.map(a=>`<tr><th>${safe(a)}</th>${sch.map(b=>cell(a,b)).join('')}</tr>`).join('')}</tbody></table></div>${evidenceLegend()}` }
function parameters(){return section('The experiment board','Each dial changes a different part of generation. Find stable regions, not just one lucky maximum.')+plotControls()+`<div class="grid-two">${panel('Encoder CFG','GUIDANCE RESPONSE',linePlot(groups('encoder_cfg')))}${panel('Sampling steps','ITERATION RESPONSE',linePlot(groups('sampler_steps')))}${panel('Top-k','CONDITIONING DIVERSITY',linePlot(groups('top_k')))}${panel('Sampler CFG','DIFFUSION GUIDANCE',linePlot(groups('sampler_cfg')))}${panel('The pairing matrix','ALGORITHM × SCHEDULE',heat(),'Blank cells represent combinations that were not tested.',true)}${panel('Caption length','WORD COUNT',barPlot(binned('caption_words').reverse(),{limit:9,sort:'input'}))}${panel('Lyrics length','WORD COUNT',barPlot(binned('lyrics_words').reverse(),{limit:9,sort:'input'}))}</div>`}
function binned(field,n=7){const a=filtered.filter(r=>r[field]!=null&&Number.isFinite(+r[field]));if(!a.length)return [];const vals=a.map(r=>+r[field]),lo=Math.min(...vals),hi=Math.max(...vals),step=(hi-lo||1)/n;return groups(r=>r[field]==null?'Unknown':`${Math.floor((+r[field]-lo)/step)<n?Math.floor((+r[field]-lo)/step):n-1}`).filter(x=>x.name!=='Unknown').map(x=>{const i=+x.name;return {...x,name:`${fix(lo+i*step,0)}–${fix(lo+(i+1)*step,0)}`}})}
function genres(){
 const songs=groups('title').filter(g=>g.name!=='Unknown');
 const clusters=groups('cluster').filter(g=>g.name!=='Unknown');
 const ranked=orderGroups(songs.filter(g=>g.n>=minimumN),'score');
 const floor=ranked.slice(0,12);
 const most=orderGroups(songs,'count').slice(0,14);
 return section('Composition comparisons','Every row represents a composition, with the sample count beside its observed rating. Use the genre and caption-source filters to compare relevant subsets.')+
 `<div class="grid-two">${panel('Strongest supported compositions','MINIMUM '+minimumN+' RECORDINGS',barPlot(floor,{sort:'input',limit:12}),'Ranks only compositions meeting the sample threshold.',true)}${panel('Most tested compositions','ATTEMPT VOLUME',barPlot(most,{sort:'input',limit:14}),'These are the songs with most generations, not necessarily the best.')}${panel('Genre cluster comparison','MEAN QUALITY',barPlot(clusters,{sort:'score',limit:16}),'Rating differences also reflect song selection and caption choices.',true)}</div>`;
}
let signalA='',signalB='';
function audio(){
 if(isPlatform())return platformSignal();
 const metrics=[['bpm','Tempo','BPM','Estimated beat rate; can report half-time or double-time.'],['onset_density','Rhythmic activity','attacks/sec','How frequently transients appear; high is busier, not better.'],['energy_std','Dynamic movement','relative','Variation in signal energy; high suggests more intensity changes.'],['bass_mean','Low-frequency content','relative','Strength of bass frequencies; not a bass-instrument detector.'],['brightness_mean','Brightness','relative','Higher-frequency emphasis; does not establish mix quality.'],['change_mean','Sonic movement','relative','How much the audio features change over time.']];
 const rs=filtered.filter(r=>metrics.every(([k])=>r[k]!==null&&Number.isFinite(Number(r[k]))));
 if(!rs.length)return section('Signal anatomy','No fully analysed audio profiles in this selection.');
 const choices=rs.slice().sort((a,b)=>String(a.audio_file).localeCompare(String(b.audio_file)));
 const a=choices.find(r=>r.id===signalA)||choices[0],b=choices.find(r=>r.id===signalB)||choices.find(r=>r.id!==a.id)||a;
 signalA=a.id;signalB=b.id;
 const values=metrics.map(([k])=>rs.map(r=>+r[k]).sort((x,y)=>x-y));
 const rank=(v,arr)=>arr.length<=1?50:100*arr.filter(x=>x<=v).length/arr.length;
 const scores=[a,b].map(r=>metrics.map(([k],i)=>rank(+r[k],values[i])));
 const centre=210,radius=137,point=(i,v)=>{const th=-Math.PI/2+i*Math.PI*2/metrics.length;return [(centre+Math.cos(th)*radius*v/100).toFixed(1),(centre+Math.sin(th)*radius*v/100).toFixed(1)]};
 const poly=(vals)=>vals.map((v,i)=>point(i,v).join(',')).join(' ');
 const chart=`<svg class="signal-radar" viewBox="0 0 420 420" role="img" aria-label="Percentile radar comparison of two selected tracks">${[25,50,75,100].map(k=>`<polygon points="${poly(metrics.map(()=>k))}" fill="none" stroke="#827354" stroke-opacity=".34"/>`).join('')}${metrics.map(([,name],i)=>{const [x,y]=point(i,100);const [lx,ly]=point(i,117);return `<line x1="210" y1="210" x2="${x}" y2="${y}" stroke="#827354" stroke-opacity=".3"/><text x="${lx}" y="${ly}" text-anchor="middle" dominant-baseline="middle" font-size="10" fill="#e2c9a2">${safe(name)}</text>`}).join('')}<polygon points="${poly(scores[0])}" fill="#e4b45b" fill-opacity=".2" stroke="#e4b45b" stroke-width="2.5"/><polygon points="${poly(scores[1])}" fill="#89bb9f" fill-opacity=".2" stroke="#89bb9f" stroke-width="2.5"/><text x="210" y="209" text-anchor="middle" fill="#d5c8ae" font-size="10">PERCENTILE</text></svg>`;
 const select=(id,chosen)=>`<select id="${id}" aria-label="Choose comparison recording">${choices.map(r=>`<option value="${safe(r.id)}" ${r.id===chosen?'selected':''}>${safe(r.audio_file||r.title||r.id)} · ${score(r)}/5</option>`).join('')}</select>`;
 const explain=metrics.map(([key,name,unit,desc],i)=>{const x=+a[key],y=+b[key],gap=Math.abs(scores[0][i]-scores[1][i]);return `<div class="signal-fact"><strong>${safe(name)}</strong><p>${safe(desc)}</p><div><span style="color:#e4b45b">A: ${fix(x,unit==='BPM'?0:2)} ${unit} · ${Math.round(scores[0][i])}th percentile</span><span style="color:#89bb9f">B: ${fix(y,unit==='BPM'?0:2)} ${unit} · ${Math.round(scores[1][i])}th percentile</span></div>${gap>=20?`<small>Notable acoustic difference: ${Math.round(gap)} percentile points.</small>`:''}</div>`}).join('');
 return section('Signal anatomy / Listening fingerprints','Compare two real recordings and discover what sounds different. These are acoustic characteristics, not scores for how good the music is.')+`<div class="signal-compare-head"><label><b>RECORDING A</b>${select('signalA',a.id)}</label><label><b>RECORDING B</b>${select('signalB',b.id)}</label></div><div class="signal-comparison"><div class="signal-radar-panel"><div class="signal-key"><span style="color:#e4b45b">● A · grade ${score(a)}/5</span><span style="color:#89bb9f">● B · grade ${score(b)}/5</span></div>${chart}<p>The centre means low relative to the current selection; the outer ring means high. The axes are percentiles, not audio units or a quality score.</p></div><div class="signal-facts"><h2>What actually differs?</h2>${explain}</div></div><div class="signal-caveat"><strong>Is higher good?</strong> Not inherently. More bass, higher tempo or greater activity can suit one genre and harm another. Compare recordings of the same song or style for a more meaningful interpretation. These profiles cannot diagnose clipping, vocal intelligibility, lyrical accuracy or adherence to your prompt.</div>`;
}
let audioFeature='bpm';
let costDataset=null;
function costMoney(n){return Number.isFinite(n)?'$'+n.toFixed(n<.1?4:2):'—'}
function computeCost(){
 if(isPlatform())return platformCompute();
 if(!costDataset)return panel('Cost telemetry','NOT IMPORTED',`<div class="empty">Pipeline cost data is not yet imported. Refresh the public research export from the shared GBR database. No estimated prices are substituted.</div>`,'Pipeline data is independent of FLAC profiling.',true);
 const d=costDataset;const selection=new Set(filtered.map(x=>x.id));const linked=(d.matched_generations||[]).filter(x=>selection.has(x.generation_id));const reviewed=linked.filter(x=>x.quality_score!=null&&x.stages&&x.stages.includes('conditioning_total')&&x.stages.includes('sampling_total'));const accepted=reviewed.filter(x=>Number(x.quality_score)>=4);const rejected=reviewed.filter(x=>Number(x.quality_score)===0);const priced=reviewed.reduce((v,x)=>v+Number(x.cost_usd||0),0);
 const overall=panel('Cost / benefit register','MATCHED REVIEWED GENERATIONS',`<div class="cost-stat-grid"><div><small>MATCHED REVIEWS</small><strong>${reviewed.length}</strong></div><div><small>COST PER REVIEWED ATTEMPT</small><strong>${reviewed.length?costMoney(priced/reviewed.length):'—'}</strong></div><div><small>COST PER SCORE ≥4</small><strong>${accepted.length?costMoney(priced/accepted.length):'—'}</strong></div><div><small>SCORE 0</small><strong>${rejected.length}</strong></div></div><p class="subtext">These estimates include the cost of rejected attempts and only count generations with both conditioning and sampling stage totals in the matched reviewed cohort. They exclude unrated attempts and cannot be treated as total pipeline cost. Source matched ${d.matched_count} unique generations out of ${d.source_rows} timing rows.</p>`, '',true);
 const ws=d.workers||[];
 const workerPanel=panel('Pod cost ledger','PIPELINE BILLABLE STAGES',`<div class="plot"><table class="vault-table"><thead><tr><th>POD</th><th>GPU</th><th>EST. SPEND</th><th>BILLABLE ROWS</th><th>WORKER HOURS</th></tr></thead><tbody>${ws.map(x=>`<tr><td><strong>${safe(x.worker)}</strong></td><td>${safe(x.gpu)}</td><td>${costMoney(+x.cost_usd)}</td><td>${x.billable_rows}</td><td>${fix(+x.worker_seconds/3600,2)}</td></tr>`).join('')}</tbody></table></div>`,'Stage totals are costed; nonbillable sub-stages are not added a second time.',true);
 const map=new Map();for(const x of reviewed){const key=`${x.text_encoder||'Unknown'} / ${x.dit||'Unknown'}`;if(!map.has(key))map.set(key,[]);map.get(key).push(x)}
 const efficiency=[...map].map(([key,x])=>{const successes=x.filter(r=>+r.quality_score>=4);const cost=x.reduce((v,r)=>v+(+r.cost_usd||0),0);return {key,n:x.length,success:successes.length,rate:successes.length/x.length,cost,per:successes.length?cost/successes.length:null}}).sort((a,b)=>(a.per??Infinity)-(b.per??Infinity));
 const efficiencyPanel=panel('Precision value','ENCODER / DiT',`<div class="plot"><table class="vault-table"><thead><tr><th>ENC / DiT</th><th>REVIEWED</th><th>4–5</th><th>SUCCESS %</th><th>EST. $ / SCORE ≥4</th></tr></thead><tbody>${efficiency.map(x=>`<tr><td><strong>${safe(x.key)}</strong></td><td>${x.n}${x.n<minimumN?' · LOW N':''}</td><td>${x.success}</td><td>${fix(x.rate*100,1)}%</td><td>${x.n<minimumN?'Exploratory · ':''}${x.per!=null?costMoney(x.per):'No accepts'}</td></tr>`).join('')}</tbody></table></div>`,'Raw success rates and costs are exploratory at small sample sizes; matched generations only.',true);
 const audit=panel('Match integrity','NO ASSUMED COST ASSIGNMENTS',`<div class="cost-stat-grid"><div><small>UNMATCHED BILLABLE ROWS</small><strong>${d.unmatched_rows}</strong></div><div><small>AMBIGUOUS PATHS</small><strong>${d.ambiguous_rows}</strong></div><div><small>SKIPPED / NONBILLABLE</small><strong>${d.skipped_rows}</strong></div><div><small>VERIFIED LINKS</small><strong>${d.matched_count}</strong></div></div><p class="subtext">If the match count is low, add stable generation IDs or exact FLAC names to the runner telemetry. Pod spend is shown separately from quality until identities match.</p>`,d.warning||'',true);
 return overall+`<div class="grid-two">${workerPanel}${efficiencyPanel}${audit}</div>`;
}
function precisionMatrix(){
 const rs=filtered.filter(r=>rated(r)&&r.text_encoder&&r.dit);
 const enc=[...new Set(rs.map(r=>r.text_encoder))].sort(),dit=[...new Set(rs.map(r=>r.dit))].sort();
 const cell=(e,d)=>{const a=rs.filter(r=>r.text_encoder===e&&r.dit===d);if(!a.length)return '<td class="matrix-absent" title="Not tested">—<small>n=0</small></td>';const g=evidence({name:e+' / '+d,n:a.length,avg:average(a.map(score)),rows:a});const val=evidenceMode==='raw'?g.avg:g.adjusted;const alpha=g.eligible?.10+val/5*.50:.06;return `<td class="${g.eligible?'':'tentative'}" style="background:rgba(229,177,88,${alpha.toFixed(2)})" title="${safe(meanTooltip(g))}"><strong>${fix(val)}</strong><small>n=${a.length}</small>${!g.eligible?'<small>LOW N</small>':''}</td>`};
 return `<div class="matrix-axis-top">DiT model / precision <span>→ COLUMNS</span></div><div class="matrix-axis-layout"><div class="matrix-axis-left">Text encoder model / precision <span>↓ ROWS</span></div><div class="plot matrix-scroll"><table class="heat-table precision-matrix"><thead><tr><th>ENCODER / DiT</th>${dit.map(x=>`<th>${safe(x)}</th>`).join('')}</tr></thead><tbody>${enc.map(e=>`<tr><th>${safe(e)}</th>${dit.map(d=>cell(e,d)).join('')}</tr>`).join('')}</tbody></table></div></div><p class="subtext">Colour = quality mean · Number = adjusted rating out of 5 · n = actual generations · — = untested. Dim cells have fewer than ${minimumN} observations.</p>`;
}
function precision(){return section('Encoder × DiT comparison','Rows are text-encoder models; columns are DiT models. Each cell shows actual reviewed generations and their rating, with low-sample results marked as exploratory.')+panel('Model precision matrix','ACTUAL OBSERVATIONS · ENCODER ↓ / DiT →',precisionMatrix(),'Count n means the number of recordings tested with that encoder–DiT combination.',true)+section('Efficiency laboratory','Cost data remains separate from quality scoring.')+computeCost()}
function archive(){const a=filtered.slice(page*LIMIT,(page+1)*LIMIT);return section('The complete experiment log','Choose a recording to inspect its exact YAML values and acoustic profile.')+`<div class="instrument"><div class="archive-controls"><span>SHOWING ${filtered.length?1+page*LIMIT:0}–${Math.min((page+1)*LIMIT,filtered.length)} / ${filtered.length} GENERATIONS</span><div><button id="prev" ${page===0?'disabled':''}>← PREV</button> <button id="next" ${(page+1)*LIMIT>=filtered.length?'disabled':''}>NEXT →</button></div></div><div class="plot"><table class="vault-table"><thead><tr><th>COMPOSITION</th><th>STYLE / VERSION</th><th>CLUSTER</th><th>GRADE</th><th>AUDIO</th><th>ENC / DiT</th></tr></thead><tbody>${a.map(r=>`<tr data-record="${safe(r.id)}"><td><strong>${safe(r.title||r.audio_file||'Unidentified')}</strong></td><td>${safe(r.version||'—')}</td><td>${safe(r.cluster||'—')}</td><td><span class="score grade${Math.floor(score(r))}">${rated(r)?fix(score(r),isPlatform()?2:0):"—"}</span></td><td><span class="chip">${r.duration!=null?'PROFILED':'MISSING'}</span></td><td>${safe(r.text_encoder||'?')} / ${safe(r.dit||'?')}</td></tr>`).join('')}</tbody></table></div></div>`}
function detail(id){const r=rows.find(x=>x.id===id);if(!r)return;const fields=[['SELECTED REVIEW RESPONSE',rated(r)?`${fix(score(r))} / 5`:'Unreviewed'],['GENRE CLUSTER',r.cluster],['GENRE VERSION',r.version],['MODEL',r.model],['ENCODER PRECISION',r.text_encoder],['DiT PRECISION',r.dit],['ENCODER CFG',r.encoder_cfg],['SAMPLER CFG',r.sampler_cfg],['TOP K',r.top_k],['SAMPLER STEPS',r.sampler_steps],['SAMPLER',r.sampler],['SCHEDULER',r.scheduler],['ENCODER SEED',r.encoder_seed],['SAMPLER SEED',r.sampler_seed],['LENGTH / SEC',r.duration],['TEMPO / BPM',r.bpm],['RMS / DB',r.rms_db],['PEAK / DB',r.peak_db],['ONSET DENSITY',r.onset_density],['ENERGY VARIATION',r.energy_std],['BASS ENERGY',r.bass_mean],['BRIGHTNESS',r.brightness_mean],['CAPTION WORDS',r.caption_words],['LYRIC WORDS',r.lyrics_words],['YAML FILE',r.yaml_file],['AUDIO FILE',r.audio_file],['CATALOGUE',r.published?'Matched to GBR':'Research / unmatched']];$('drawerId').textContent=String(r.id).slice(0,9);$('drawerBody').innerHTML=`<div class="eyebrow" style="margin-top:27px">ORIGINAL EXPERIMENT RECORD</div><h2>${safe(r.title||r.audio_file||'Unidentified recording')}</h2><p style="color:#b5a48a">${safe(r.version||r.cluster||'Unclassified')}</p><div class="drawer-grid">${fields.map(([label,value])=>`<div class="drawer-field"><small>${safe(label)}</small><strong>${safe(value??'—')}</strong></div>`).join('')}</div>${researchDetail(r)}`;$('scrim').hidden=false;$('drawer').classList.add('open');$('drawer').setAttribute('aria-hidden','false')}
