function render(){document.body.classList.toggle('explorer-active',view==='explorer');const [k,h,sub]=labels[view];$('kicker').textContent=k;$('headline').innerHTML=h;$('subtitle').textContent=sub;const ratedRows=filtered.filter(rated),good=ratedRows.filter(r=>score(r)>=4).length,profile=filtered.filter(r=>isPlatform()?Object.values(r.audio_analysis||{}).some(observed):r.duration!=null).length,mean=average(ratedRows.map(score));$('metrics').innerHTML=[['RECORDINGS',filtered.length.toLocaleString(),`${ratedRows.length} REVIEWED`],['MEAN REVIEW RESPONSE',fix(mean),'OUT OF FIVE'],['SCORE ≥4',ratedRows.length?fix(good/ratedRows.length*100,1)+'%':'—',`${good} HIGH SCORERS`],['AUDIO PROFILES',profile.toLocaleString(),`${filtered.length?fix(profile/filtered.length*100,1):'0'}% OF SELECTION`]].map(([a,b,c])=>`<div class="meter"><small>${a}</small><strong>${b}</strong><em>${c}</em></div>`).join('');$('viewContent').innerHTML=({explorer:explorerView,overview,parameters,genres,audio,precision,archive,tags:reviewTags,simulator:explorerView})[view]();document.querySelectorAll('#nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelectorAll('[data-plot-scale]').forEach(b=>b.addEventListener('click',()=>{plotScale=b.dataset.plotScale;render()}));document.querySelectorAll('[data-record]').forEach(tr=>tr.addEventListener('click',()=>detail(tr.dataset.record)));document.querySelectorAll('.song-star').forEach(el=>{el.style.cursor='pointer';el.addEventListener('click',()=>{$('song').value=el.dataset.song;apply();})});if(view==='simulator')wireSimulator();if(view==='explorer')wireExplorer();if(view==='audio'){for(const id of ['signalA','signalB']){const el=$(id);if(el)el.onchange=()=>{if(id==='signalA')signalA=el.value;else signalB=el.value;render()}}}document.querySelectorAll('[data-audio-feature]').forEach(b=>b.onclick=()=>{audioFeature=b.dataset.audioFeature;render()});if($('prev'))$('prev').onclick=()=>{page--;render()};if($('next'))$('next').onclick=()=>{page++;render()}}
function apply(){const s=$('search').value.toLowerCase().trim(),song=$('song').value,cluster=$('cluster').value,grade=$('grade').value,caption=$('captionSource').value;filtered=rows.filter(r=>(!caption||(caption==='missing'?!r.caption_source:r.caption_source===caption))&&(!song||r.title===song)&&(!cluster||r.cluster===cluster)&&researchGrade(r,grade)&&researchMatches(r)&&(!s||[r.title,r.cluster,r.version,r.audio_file,r.sampler,r.scheduler].some(v=>String(v||'').toLowerCase().includes(s))));page=0;render()}
